import{z as l,x as B,o as t,c as d,q as E,j as i,D as r,d as s,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"定点 DSP 运算","description":"","frontmatter":{"title":"定点 DSP 运算","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fixed-point-dsp.md","filePath":"cs/fixed-point-dsp.md","lastUpdated":1791413859000}'),p={name:"cs/fixed-point-dsp.md"};function D(m,a,C,f,c,u){const n=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=E('<h1 id="定点-dsp-运算" tabindex="-1">定点 DSP 运算 <a class="header-anchor" href="#定点-dsp-运算" aria-label="Permalink to &quot;定点 DSP 运算&quot;">​</a></h1><div class="epigraph"><p>小数点钉在位域里某处，乘加就是整数乘加再约定截位；没有对阶，也没有 NaN，溢出得自己决定是环绕还是饱和。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V)；ITU-T G.191 / 常见定点 DSP 约定 整理</footer></div><p><a href="/cs/lzc-normalize">上一课</a>让浮点用 LZC 把小数点挪回隐藏位之前。许多信号路径（音频、控制环、早期基带）并不需要 754 的动态范围，却需要确定的延迟与更小的面积。缺口是：<strong>定点小数</strong>——同一套<a href="/cs/array-multiplier">阵列乘</a>与加法器，二进制点由程序员或 ISA 约定钉死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Q15、Q31 一类格式：16/32 位里 1 位符号、其余是分数。乘：两个 Q15 得 Q30，往往左移 1 位丢掉多余符号位，再截回 Q15。MAC：累加器比乘数更宽，防止一串加立刻溢出。缺口不是再讲浮点对阶，而是：没有指数、没有<a href="/cs/fp-exceptions">五类标志</a>的默认递送，<strong>溢出策略</strong>必须另选——环绕（补码模 \\(2^n\\)）或下一课的检测/再下一课的饱和。</p><p><span class="marginnote">数字实例：Q15 把 16 位切成 1 位符号 + 15 位分数：0x4000 就是 0.5，0x2000 就是 0.25，一切值都是 \\(n/32768\\)。0x8000 代表 −1.0，而 DSP 口中的「1.0」其实是 0x7FFF ≈ 0.99997——满量程那一位被符号占用了。</span></p><p>FPGA DSP 块、ASIC MAC 都是这条通路的硬化。本课不把它们写成厂商原语清单。</p><h3 id="定点不是「精度更差的浮点」" tabindex="-1">定点不是「精度更差的浮点」 <a class="header-anchor" href="#定点不是「精度更差的浮点」" aria-label="Permalink to &quot;定点不是「精度更差的浮点」&quot;">​</a></h3><p>误差模型不同：定点是绝对量化步长恒定（在满量程内），浮点是相对（ulp 随指数变）。把定点当 <code>float</code> 关掉规格化，舍入与溢出语义都不对。DSP 里的「1.0」常常是 <code>0x7FFF</code>，没有 754 的 +inf。</p><p><span class="marginnote">Harris 把定点当作二进制小数点的位置。Patterson/Hennessy 用定点对照浮点。本课不进入限价簿或金融定点货币——那是量化栏；这里是 ALU 数据通路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约定格式 \\(Qm.n\\)。加：先对齐二进制点（通常已对齐），整数加。乘：整数乘，二进制点位置相加，再移位到目标格式，按截断或四舍五入取位。累加器宽度 \\(m+n+\\text{guard}\\)。舍入用多出来的低位，但没有 754 的五种模式义务——实现选定一种。</p>',12)),(t(),i(A,null,{default:r(()=>[o(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FMT%5B%22%E9%92%89%E6%AD%BB%E7%9A%84%E4%BA%8C%E8%BF%9B%E5%88%B6%E7%82%B9%22%5D%20--%3E%20MUL%5B%22%E6%95%B4%E6%95%B0%E4%B9%98%22%5D%0A%20%20MUL%20--%3E%20SHIFT%5B%22%E7%A7%BB%E4%BD%8D%E5%88%B0%E7%9B%AE%E6%A0%87%20Q%20%E6%A0%BC%E5%BC%8F%22%5D%0A%20%20SHIFT%20--%3E%20ACC%5B%22%E5%AE%BD%E7%B4%AF%E5%8A%A0%E5%99%A8%22%5D%0A%20%20ACC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%BA%A2%E5%87%BA%E6%A3%80%E6%B5%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 FMA 对照：定点 MAC 通常每步截入累加器或保持全宽直到输出，由设计者选；没有「754 强制一次正确舍入」的同一合同，除非产品规范另写。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：加宽的累加器像用更深的碗接水——两个 16 位数相乘最多 32 位，连加 256 个 Q30 乘积最多再涨 8 位，40 位累加器就是为这些「涨出来的位数」预留的深度，整串乘加中途不必截断。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"后两课整数溢出检测与饱和，正是定点 DSP 的收尾策略。浮点用指数和 NaN；定点用标志位或饱和到满量程。后课 HDL 会看到这些 MAC 被写成流水线与时钟使能，本课只钉算术。",-1)),(t(),i(A,null,{default:r(()=>[o(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22Q15%20%E6%95%B0%20a%3A%2016%20%E4%BD%8D%22%5D%20--%3E%20P%5B%22%E6%95%B4%E6%95%B0%E4%B9%98%3A%2032%20%E4%BD%8D%E4%B9%98%E7%A7%AF%22%5D%0A%20%20B%5B%22Q15%20%E6%95%B0%20b%3A%2016%20%E4%BD%8D%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20Q%5B%22Q30%20%E6%A0%BC%E5%BC%8F%3A%20%E7%AC%A6%E5%8F%B7%E4%BD%8D%E5%A4%9A%E5%8D%A0%E4%B8%80%E6%A0%BC%22%5D%0A%20%20Q%20--%3E%7C%22%E5%B7%A6%E7%A7%BB%201%20%E4%BD%8D%E5%8E%BB%E6%8E%89%E5%A4%9A%E4%BD%99%E7%AC%A6%E5%8F%B7%22%7C%20R%5B%22%E5%8F%96%E9%AB%98%E4%BD%8D%E6%88%AA%E5%9B%9E%20Q15%22%5D%0A%20%20Q%20--%3E%7C%22%E6%88%96%E4%BF%9D%E6%8C%81%E5%85%A8%E5%AE%BD%22%7C%20S%5B%22%E9%80%81%E5%85%A5%2040%20%E4%BD%8D%E7%B4%AF%E5%8A%A0%E5%99%A8%22%5D%0A%20%20S%20--%3E%20T%5B%22%E6%95%B4%E4%B8%B2%20MAC%20%E4%B8%8D%E6%98%93%E6%BA%A2%E5%87%BA%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">常见误区：初学者以为溢出环绕「只是数字怪一点」。音频里正弦波顶被卷到负值，听感是刺耳的破裂声；饱和只是削平波峰。这就是为什么溢出策略要在产品层面选定，而不是让编译器随手替你选。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲块浮点（每块一个共享指数），不把 SIMD 打包定点写成 NEON 指令表。不重写 Transformer 的量化感知训练。不进入光刻成像或限价簿。</p><p>后课默认：定点乘加是整数乘加加移位；溢出尚未规定如何呈现。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>浮点靠指数与 LZC；定点靠约定的二进制点。</li><li>MAC 用宽累加器；截位规则是实现合同。</li><li>溢出策略下一课起才钉。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',6))])}const S=l(p,[["render",D]]);export{P as __pageData,S as default};
